insert into CHB_EQUDET( BUSI_SEQNO,ACCOUNT,ACCOUNT_NAME,REGIST_BANK_CODE,INDENTIFY_MARK, EQUITY_CONF_DATE,BUY_PLACE,BUSI_TYPE,CCY,AMOUNT,COVER_CNY_AMOUNT, SHARES,CHANNEL,FUND_ACC,FUND_ACC_BANK,IS_SUBMIT,IS_CONSIGN,REMARK, DATA_SOURCE,STATUS,WORKFLOW_ID,DEPT_CODE,UPDATE_USER,UPDATE_TIME, CREATE_USER,CREATE_TIM) select BUSI_SEQNO,ACCOUNT,ACCOUNT_NAME,REGIST_BANK_CODE,INDENTIFY_MARK, EQUITY_CONF_DATE,BUY_PLACE,BUSI_TYPE,CCY,AMOUNT,COVER_CNY_AMOUNT, SHARES,CHANNEL,FUND_ACC,FUND_ACC_BANK,IS_SUBMIT,IS_CONSIGN,REMARK, DATA_SOURCE,STATUS,WORKFLOW_ID,DEPT_CODE,UPDATE_USER,UPDATE_TIME, CREATE_USER,CREATE_TIM from ( select TEMP.* from (
SELECT #{item.busiSeqno,jdbcType=VARCHAR} AS BUSI_SEQNO, #{item.account,jdbcType=VARCHAR} AS ACCOUNT, #{item.accountName,jdbcType=VARCHAR} AS ACCOUNT_NAME, #{item.registBankCode,jdbcType=VARCHAR} AS REGIST_BANK_CODE, #{item.indentifyMark,jdbcType=VARCHAR} AS INDENTIFY_MARK, #{item.eQuityConfDate,jdbcType=DATE} AS EQUITY_CONF_DATE #{item.buyPlace,jdbcType=VARCHAR} AS BUY_PLACE #{item.busiType,jdbcType=CHAR} AS BUSI_TYPE #{item.ccy,jdbcType=CHAR} AS CCY #{item.amount,jdbcType=DOUBLE} AS AMOUNT #{item.converCnyAmount,jdbcType=DOUBLE} AS COVER_CNY_AMOUNT #{item.shares,jdbcType=DOUBLE} AS SHARES #{item.channel,jdbcType=CHAR} AS CHANNEL #{item.fundAcc,jdbcType=VARCHAR} AS FUND_ACC #{item.fundAccBank,jdbcType=VARCHAR} AS FUND_ACC_BANK #{item.isSubmit,jdbcType=CHAR} AS IS_SUBMIT #{item.isConsign,jdbcType=VARCHAR} AS IS_CONSIGN #{item.remark,jdbcType=VARCHAR} AS REMARK #{item.dataSource,jdbcType=CHAR} AS DATA_SOURCE #{item.status,jdbcType=VARCHAR} AS STATUS #{item.workflowId,jdbcType=VARCHAR} AS WORKFLOW_ID #{item.createDept,jdbcType=VARCHAR} AS DEPT_CODE #{item.updateUser,jdbcType=VARCHAR} AS UPDATE_USER #{item.updateTime,jdbcType=TIMESTAMP} AS UPDATE_TIME #{item.createUser,jdbcType=VARCHAR} AS CREATE_USER #{item.createTime,jdbcType=TIMESTAMP} AS CREATE_TIME FROM DUAL
) TEMP where not exists (select 1 from CHB_EQUDET CII where TEMP.BUSI_SEQNO= CII.BUSI_SEQNO AND TEMP.INDENTIFY_MARK = CII.INDENTIFY_MARK AND TEMP.REGIST_BANK_CODE = CII.REGIST_BANK_CODE) ) de ;
UPDATE CHB_EQUDET as A, ( select A.* from ( select TEMP.* from (
SELECT #{item.busiSeqno,jdbcType=VARCHAR} AS BUSI_SEQNO, #{item.account,jdbcType=VARCHAR} AS ACCOUNT, #{item.accountName,jdbcType=VARCHAR} AS ACCOUNT_NAME, #{item.registBankCode,jdbcType=VARCHAR} AS REGIST_BANK_CODE, #{item.indentifyMark,jdbcType=VARCHAR} AS INDENTIFY_MARK, #{item.eQuityConfDate,jdbcType=DATE} AS EQUITY_CONF_DATE #{item.buyPlace,jdbcType=VARCHAR} AS BUY_PLACE #{item.busiType,jdbcType=CHAR} AS BUSI_TYPE #{item.ccy,jdbcType=CHAR} AS CCY #{item.amount,jdbcType=DOUBLE} AS AMOUNT #{item.converCnyAmount,jdbcType=DOUBLE} AS COVER_CNY_AMOUNT #{item.shares,jdbcType=DOUBLE} AS SHARES #{item.channel,jdbcType=CHAR} AS CHANNEL #{item.fundAcc,jdbcType=VARCHAR} AS FUND_ACC #{item.fundAccBank,jdbcType=VARCHAR} AS FUND_ACC_BANK #{item.isSubmit,jdbcType=CHAR} AS IS_SUBMIT #{item.isConsign,jdbcType=VARCHAR} AS IS_CONSIGN #{item.remark,jdbcType=VARCHAR} AS REMARK #{item.dataSource,jdbcType=CHAR} AS DATA_SOURCE #{item.status,jdbcType=VARCHAR} AS STATUS #{item.workflowId,jdbcType=VARCHAR} AS WORKFLOW_ID #{item.createDept,jdbcType=VARCHAR} AS DEPT_CODE #{item.updateUser,jdbcType=VARCHAR} AS UPDATE_USER #{item.updateTime,jdbcType=TIMESTAMP} AS UPDATE_TIME #{item.createUser,jdbcType=VARCHAR} AS CREATE_USER #{item.createTime,jdbcType=TIMESTAMP} AS CREATE_TIME FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_EQUDET CII where TEMP.BUSI_SEQNO= CII.BUSI_SEQNO AND TEMP.INDENTIFY_MARK = CII.INDENTIFY_MARK AND TEMP.REGIST_BANK_CODE = CII.REGIST_BANK_CODE AND CII.DATA_SOURCE == '02' AND CII.isOpen == '01');

